      en: "An important industrial zone in Kourou, housing many suppliers of the nearby space center.",
      es: "Una importante zona industrial en Kourou que alberga a muchas empresas proveedoras del cercano centro espacial.",
      pt: "Uma importante zona industrial em Kourou que acolhe muitas empresas fornecedoras do centro espacial próximo.",
