      hu: ["A legfontosabb folyami kikötő a suriname-i határon.", "Trópusi rönkfa exportjára specializálódott.", "Körülbelül 15 kilométerre fekszik a folyótorkolattól a szárazföld felé.", "Az Albina (Suriname) felé irányuló kompforgalom központja.", "Támogatja a folyó felső szakaszán lévő elszigetelt közösségek ellátását.", "A vízmélység jelentősen változik az árapály függvényében."],
      ro: ["Cel mai important port fluvial la granița cu Suriname.", "Specializat în exportul de bușteni de lemn tropical.", "Situat la aproximativ 15 km în amonte de gura de vărsare a râului.", "Punct central pentru feribotul către Albina (Suriname).", "Susține aprovizionarea comunităților izolate din amonte.", "Adâncimea apei variază considerabil în funcție de maree."],
      en: ["Main river port serving the border region with Suriname.", "Specializes in the export of tropical hardwood logs.", "Located approximately 15 kilometers inland from the river mouth.", "Central point for ferry services to Albina, Suriname.", "Supports the supply chain for isolated upstream communities.", "Water depth fluctuates significantly depending on tidal conditions."],
      es: ["Puerto interior más importante en la frontera con Surinam.", "Especializado en la exportación de madera tropical en troncos.", "Se encuentra a unos 15 kilómetros tierra adentro desde la desembocadura del río.", "Punto central para el servicio de ferry hacia Albina (Surinam).", "Apoya el suministro de las comunidades aisladas en el curso superior.", "La profundidad del agua varía significativamente según el estado de la marea."],
      pt: ["O porto interior mais importante na fronteira com o Suriname.", "Especializado na exportação de toros de madeira tropical.", "Situa-se a cerca de 15 quilómetros para o interior a partir da foz do rio.", "Ponto central para o tráfego de ferry para Albina (Suriname).", "Apoia o abastecimento das comunidades isoladas no curso superior.", "A profundidade da água varia significativamente dependendo do nível da maré."],
      fr: ["Principal port intérieur à la frontière avec le Suriname.", "Spécialisé dans l'exportation de bois tropicaux en grumes.", "Situé à environ 15 kilomètres en amont de l'embouchure du fleuve.", "Point central pour le trafic de bac vers Albina (Suriname).", "Soutient l'approvisionnement des communes isolées du haut fleuve.", "La profondeur d'eau varie fortement selon le coefficient de marée."],
