      hu: ["A becsült aranytartalék meghaladja a 60 tonnát", "A helyszín a paleoproterozoikum korú Guyana-pajzson fekszik", "A kutatásokat a Nordgold és a Columbus Gold végezte", "A bányászati folyosó több kilométer hosszan nyúlik el", "Elsődleges kőzet és másodlagos hordalékos kitermelés", "Szigorú környezetvédelmi előírások az esőerdő védelmében"],
