      en: ["Located in the isolated commune of Saint-Élie", "Operated by the mining company Auplata", "Tradition dating back to the 19th-century gold rush", "Usage of cyanidation for gold extraction since 2015", "Combined mining of quartz veins and alluvial gold", "Accessible via a 13-kilometer track through the forest"],
