      hu: ["Maripasoula közelében, a suriname-i határnál fekszik", "A Maroni-Itany zöldkő-öv geológiai része", "Fő üzemeltetője a francia Auplata vállalat", "A logisztika a Maroni-folyón keresztül valósul meg", "Az arany összetett geológiai nyírási zónákban található", "Mélyfúrásos kutatásokkal tárták fel a készleteket"],
      ro: ["Situată lângă granița cu Surinam, în apropiere de Maripasoula", "Parte a centurii de roci verzi Maroni-Itany", "Operatorul principal este compania franceză Auplata", "Dependență de logistica fluvială pe râul Maroni", "Zăcăminte de aur prezente în zone de forfecare complexe", "Explorare realizată prin foraje la adâncimi mari"],
      en: ["Located near the Suriname border at Maripasoula", "Part of the mineral-rich Maroni-Itany greenstone belt", "Main operator is the French company Auplata", "Dependence on fluvial logistics on the Maroni River", "Gold deposits present in complex geological shear zones", "Exploration conducted via deep drilling programs"],
      es: ["Ubicación cerca de la frontera con Surinam en Maripasoula", "Parte del cinturón de rocas verdes de Maroni-Itany rico en minerales", "El operador principal es la empresa francesa Auplata", "Dependencia de la logística fluvial en el Maroni", "Yacimientos de oro en zonas de cizalla geológicas complejas", "Exploración mediante perforaciones hasta grandes profundidades"],
      pt: ["Localização perto da fronteira com o Suriname em Maripasoula", "Parte do cinturão de rochas verdes Maroni-Itany, rico em minerais", "O principal operador é a empresa francesa Auplata", "Dependência da logística fluvial no rio Maroni", "Jazidas de ouro em zonas de cisalhamento geológico complexas", "Exploração através de perfurações até grandes profundidades"],
      fr: ["Située près de la frontière avec le Suriname à Maripasoula", "Fait partie de la ceinture de roches vertes Maroni-Itany riche en minéraux", "L'exploitant principal est la société française Auplata", "Dépendance vis-à-vis de la logistique fluviale sur le Maroni", "Gisements d'or dans des zones de cisaillement géologique complexes", "Exploration par forages jusqu'à de grandes profondeurs"],
