      es: ["Zona minera histórica de la década de 1950", "Ubicación a unos 40 km al sur de Maripasoula", "Exploración por Reeve Resources (grupo Auplata)", "Yacimiento en la cuenca del río Petit Inini", "Oro vinculado a vetas de cuarzo en roca volcánica", "La logística se realiza principalmente por vías aéreas o pistas"],
      pt: ["Área de mineração histórica da década de 1950", "Localização cerca de 40 km ao sul de Maripasoula", "Exploração pela Reeve Resources (grupo Auplata)", "Ocorrência na bacia do rio Petit Inini", "Ouro ligado a veios de quartzo em rocha vulcânica", "Logística feita primariamente por vias aéreas ou pistas"],
