      hu: ["Kifejezetten az új Ariane–6 rakéta számára épült", "A mobil szerviztorony súlya lenyűgöző 8200 tonna", "A rakéta vízszintes integrációja a szerelőépületben", "Az Ariane–6 első sikeres indítása 2024 júliusában történt", "Innovatív vízelárasztó rendszert használ az indításkor", "A komplexum teljes területe 170 hektár"],
