      hu: ["A történelmi első Ariane-indítás helyszíne (korábban ELA–1)", "A Vega rakéta első indítása 2012 februárjában történt", "Mobil szerviztorony védi a rakétát az indítás előtt", "Kis és közepes műholdak pályára állítására optimalizálták", "A szilárd hajtóanyagú motorok speciális gázelvezetést igényelnek", "A modernizált Vega–C hordozórakéták bázisa"],
