      ro: "O rampă de lansare lângă Sinnamary, construită în colaborare cu Rusia pentru rachetele Soiuz, pentru a lansa sarcini utile medii.",
      en: "A launch pad near Sinnamary built in cooperation with Russia for Soyuz rockets to launch medium payloads.",
      es: "Una rampa de lanzamiento cerca de Sinnamary, construida en colaboración con Rusia para los cohetes Soyuz con el fin de lanzar cargas útiles medias.",
      pt: "Uma rampa de lançamento perto de Sinnamary, construída em colaboração com a Rússia para foguetes Soyuz, com o objetivo de lançar cargas úteis médias.",
